void dei_ask_task(void)
{
    while(1)
    {
        if( dei_ask_receive(0) )        
        {      
            if(dei_ask.programming_on)
            {                                
                dei_ask_handle_frame_programming_mode();
            }
            else
            {
                dei_ask_handle_frame_normal_mode(); 
            }                                                                    
        }                               
    }                        
}

